def shortest_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[Union[float, int], List[int]]:
    # Initialize distances to all nodes as infinity except the source node
    distances: Dict[int, Union[float, int]] = {node: math.inf for node in graph}
    distances[source] = 0  # Distance to the source node is 0

    # Priority queue with pairs (distance, node)
    priority_queue: List[Tuple[Union[float, int], int]] = [(0, source)]

    # Path dictionary to keep track of the shortest path to each node
    path: Dict[int, List[int]] = {node: [] for node in graph}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reached the target node, reconstruct the path
        if current_node == target:
            path[target] = []
            node = target
            while node != source:
                path[target].insert(0, node)
                for neighbor, weight in graph[node]:
                    if current_distance - weight == distances[neighbor]:
                        node = neighbor
                        break
            path[target].insert(0, source)
            return (current_distance, path[target])

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))
                # Update the path to the neighbor
                path[neighbor] = path[current_node] + [neighbor]

    # If the target node is unreachable
    return (math.inf, None)
