def shortest_path(graph, source, target):
    import heapq
    from collections import deque

    # Queue for BFS: [(distance, path, current_node)]
    queue = deque([(0, [source], source)])  # Distance, path, current node
    visited = set()

    while queue:
        (distance, path, current_node) = queue.popleft()

        if current_node == target:
            return (distance, path)  # Found a path to target node

        if current_node not in visited:
            visited.add(current_node)
            for (neighbor, weight) in graph.get(current_node, []):
                if neighbor not in visited:
                    queue.append((distance + weight, path + [neighbor], neighbor))

    # If the queue is exhausted and target is not found, it's unreachable
    return (float("inf"), None)

