def shortest_path(graph, source, target):
    # Initialize the distance dictionary and the previous node dictionary
    distance = {node: float("inf") for node in graph}
    previous = {node: None for node in graph}
    distance[source] = 0 # Distance from source to itself is 0

    # Define the priority queue and the explored set
    queue = [(0, source)]
    explored = set()

    while queue:
        # Get the minimum distance node
        current_distance, current_node = min(queue)

        if current_node == target:
            # Reconstruct the path from target to source
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = previous[current_node]
            return (current_distance, path[::-1])

        explored.add(current_node)
        queue.remove((current_distance, current_node))

        # Explore neighbors
        for neighbor, weight in graph.get(current_node, []):
            if neighbor in explored:
                continue

            new_distance = current_distance + weight
            if new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                previous[neighbor] = current_node

                # If the neighbor has been visited, update the priority queue
                if (new_distance, neighbor) in queue:
                    queue.remove((new_distance, neighbor))
                queue.append((new_distance, neighbor))

    # If target is unreachable, return infinity and None
    return (float("inf"), None)
