        for neighbour, weight in graph.get(current, []):
            distance_through_current = distances[current] + weight
            if distance_through_current < distances[neighbour]:
                distances[neighbour] = distance_through_current
                previous[neighbour] = current
                if neighbour not in queue:
                    queue.append(neighbour)

    # If there is no path from source to target
    if previous[target] is None:
        return float("inf"), None

    # Construct the path
    path = []
    current = target
    while current is not None:
        path.insert(0, current)
        current = previous.get(current)

