def shortest_path(graph, source, target):
    # Initialize distances and previous nodes
    distances = {node: float("inf") for node in graph}
    distances[source] = 0
    previous = {node: None for node in graph}

    # Initialize a set of unvisited nodes
    unvisited = set(graph.keys())

    while unvisited:
        # Select the closest unvisited node
        closest_node = min(unvisited, key=lambda node: distances[node])
        unvisited.remove(closest_node)

        # If we've reached the target, stop
        if closest_node == target:
            break

        # Explore neighbors
        for neighbor, weight in graph.get(closest_node, []):
            if neighbor in unvisited:
                distance_through_closest_node = distances[closest_node] + weight
                if distance_through_closest_node < distances[neighbor]:
                    distances[neighbor] = distance_through_closest_node
                    previous[neighbor] = closest_node

    # If we still cannot reach target, it's unreachable
    if previous[target] is None:
        return float("inf"), None

    # Reconstruct the path
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = previous[current]

    # The path is constructed backwards, so reverse it
    return distances[target], list(reversed(path))

