def shortest_path(graph, source, target):
    # We start by initializing the previous node list, the distances to all nodes as infinity,
    # and distance to the source node as 0.
    prev = {node: None for node in graph}
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # We use a priority queue to always process the closest node first.
    import heapq
    heap = [(0, source)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # If we reached the target, we can reconstruct the path.
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = prev[current_node]
            path.reverse()
            return (current_distance, path)

        # If the current node is not target, we still need to process its neighbors.
        if current_node != target:
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                # If we find a shorter path, we update the distances and the previous nodes.
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    prev[neighbor] = current_node
                    heapq.heappush(heap, (distance, neighbor))

    # If we run out of nodes, the target is unreachable.
    return (float('inf'), None)
